        builder: (BuildContext context, AsyncSnapshot<Map<String, dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (!snapshot.hasData || snapshot.data!.isEmpty) {
            return const Center(child: Text('No data available'));
          }

          final List<CurrencyModel> currencies = snapshot.data!['currencies'] as List<CurrencyModel>;
          final List<NewsModel> news = snapshot.data!['news'] as List<NewsModel>;

          final TextStyle? sectionTitleStyle = context.fonts.regular16.copyWith(fontWeight: FontWeight.w700);

          return ListView(
            padding: const EdgeInsets.all(16),
            children: [
              // Section: Currency rates
              Text(
                loc.currencyRate,
                style: sectionTitleStyle,
              ),
              const SizedBox(height: 8),
              ...currencies.map((CurrencyModel currency) => Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: CurrencyCard(model: currency),
                  )),
              const Divider(height: 32),

              // Section: News feed
              Text(
                loc.news,
                style: sectionTitleStyle,
              ),
              const SizedBox(height: 8),
              ...news.map((NewsModel newsItem) => Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: NewsCard(model: newsItem),
                  )),
            ],
          );
        },
      ),
    );
  }
}

